"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";

import * as Primitive from "@radix-ui/react-dropdown-menu";
import { Check, Circle } from "lucide-react";
import { useEffect, useRef, useState, type ComponentProps, type ReactNode } from "react";
import { GlideHighlight, useHighlightedGlide } from "./glide-highlight";
import { cn } from "./lib/cn";
import "./shared/dropdown-content.css";
import "./dropdown-menu.css";

export const DropdownMenu = Primitive.Root;
export const DropdownMenuTrigger = Primitive.Trigger;
export const DropdownMenuGroup = Primitive.Group;
export const DropdownMenuRadioGroup = Primitive.RadioGroup;

export function DropdownMenuContent({
  className,
  sideOffset = 8,
  collisionPadding = 16,
  children,
  ...props
}: ComponentProps<typeof Primitive.Content>) {
  const [content, setContent] = useState<HTMLDivElement | null>(null);
  const box = useHighlightedGlide(content);
  return (
    <Primitive.Portal>
      <Primitive.Content
        ref={setContent}
        data-slot="dropdown-content"
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          "relative z-50 min-w-56 max-w-[calc(100vw-2rem)] max-h-[var(--radix-dropdown-menu-content-available-height)] overflow-y-auto rounded-[14px] border border-border bg-elevated p-1 text-[13px] text-foreground shadow-overlay outline-none",
          className,
        )}
        {...props}
      >
        <GlideHighlight box={box} />
        {children}
      </Primitive.Content>
    </Primitive.Portal>
  );
}

/** Row anatomy shared by every menu: dropdown, menubar and context menus. */
export const menuItemClass =
  "relative z-10 flex min-h-[34px] max-md:min-h-[var(--control-height)] cursor-default select-none items-center gap-2.5 rounded-[10px] px-2.5 text-[13px] font-normal outline-none data-[highlighted]:text-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-45 data-[variant=destructive]:text-destructive [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground data-[variant=destructive]:[&_svg]:text-destructive";

export function DropdownMenuItem({
  className,
  ...props
}: ComponentProps<typeof Primitive.Item>) {
  return (
    <Primitive.Item
      data-slot="dropdown-item"
      className={cn(menuItemClass, className)}
      {...props}
    />
  );
}
export function DropdownMenuCheckboxItem({
  className,
  children,
  ...props
}: ComponentProps<typeof Primitive.CheckboxItem>) {
  return (
    <Primitive.CheckboxItem
      data-slot="dropdown-item"
      className={cn(menuItemClass, "pl-8", className)}
      {...props}
    >
      <span className="absolute left-2.5 flex size-4 items-center justify-center">
        <Primitive.ItemIndicator>
          <Check aria-hidden="true" />
        </Primitive.ItemIndicator>
      </span>
      {children}
    </Primitive.CheckboxItem>
  );
}
export function DropdownMenuRadioItem({
  className,
  children,
  ...props
}: ComponentProps<typeof Primitive.RadioItem>) {
  return (
    <Primitive.RadioItem
      data-slot="dropdown-item"
      className={cn(menuItemClass, "pl-8", className)}
      {...props}
    >
      <span className="absolute left-2.5 flex size-4 items-center justify-center">
        <Primitive.ItemIndicator>
          <Circle className="!size-2 fill-current" aria-hidden="true" />
        </Primitive.ItemIndicator>
      </span>
      {children}
    </Primitive.RadioItem>
  );
}
export function DropdownMenuLabel({
  className,
  ...props
}: ComponentProps<typeof Primitive.Label>) {
  return (
    <Primitive.Label
      className={cn(
        "px-2.5 pb-1 pt-2 text-xs font-medium text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}
export function DropdownMenuSeparator({
  className,
  ...props
}: ComponentProps<typeof Primitive.Separator>) {
  return (
    <Primitive.Separator
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  );
}

export function DropdownMenuShortcut({
  className,
  ...props
}: ComponentProps<"span">) {
  return (
    <span
      className={cn(
        "ml-auto pl-4 font-mono text-xs tracking-wide text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

/**
 * A destructive item that asks in place: choosing it turns the row into the
 * question with Cancel and the confirming action, instead of stacking a
 * dialog on the menu. Both answers are menu items, so arrows and Enter work.
 */
export function DropdownMenuConfirmItem({
  label,
  icon,
  question,
  detail,
  confirmLabel = "Delete",
  onConfirm,
}: {
  label: string;
  icon?: ReactNode;
  /** e.g. "Delete 3 files?" */
  question: string;
  /** e.g. "They move to Trash for 30 days." */
  detail?: string;
  confirmLabel?: string;
  onConfirm: () => void;
}) {
  const [asking, setAsking] = useState(false);
  const cancel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (asking) cancel.current?.focus();
  }, [asking]);
  if (!asking) {
    return (
      <DropdownMenuItem
        data-variant="destructive"
        onSelect={(event) => {
          event.preventDefault();
          setAsking(true);
        }}
      >
        {icon}
        {label}
      </DropdownMenuItem>
    );
  }
  return (
    <div data-slot="menu-confirm" role="group" aria-label={question}>
      <p className="px-2.5 pt-2 text-[13px] font-medium text-destructive">{question}</p>
      {detail && <p className="px-2.5 pb-1 text-xs text-muted-foreground">{detail}</p>}
      <DropdownMenuItem
        ref={cancel}
        onSelect={(event) => {
          event.preventDefault();
          setAsking(false);
        }}
      >
        Cancel
      </DropdownMenuItem>
      <DropdownMenuItem data-variant="destructive" onSelect={onConfirm}>
        {icon}
        {confirmLabel}
      </DropdownMenuItem>
    </div>
  );
}

"use client";

import { useLayoutEffect, useState } from "react";
import "./glide-highlight.css";

export type GlideBox = {
  active: boolean;
  left: number;
  top: number;
  width: number;
  height: number;
};

export function glideBox(target: HTMLElement): GlideBox {
  return {
    active: true,
    left: target.offsetLeft,
    top: target.offsetTop,
    width: target.offsetWidth,
    height: target.offsetHeight,
  };
}

export function useHighlightedGlide(
  root: HTMLElement | null,
  selector = "[data-highlighted]",
  /** Attributes whose change can move the target, e.g. data-state for an open trigger. */
  attributes: readonly string[] = ["data-highlighted"],
) {
  const [box, setBox] = useState<GlideBox | null>(null);

  useLayoutEffect(() => {
    const element = root;
    if (!element) return;
    const update = () => {
      const target = element.querySelector<HTMLElement>(selector);
      setBox((current) =>
        target ? glideBox(target) : current ? { ...current, active: false } : null,
      );
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(element, {
      subtree: true,
      attributes: true,
      attributeFilter: [...attributes],
    });
    return () => observer.disconnect();
    // The attribute list is fixed per call site.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, selector]);

  return box;
}

export function GlideHighlight({ box }: { box: GlideBox | null }) {
  if (!box) return null;
  return (
    <span
      aria-hidden="true"
      data-slot="glide-highlight"
      data-active={box.active}
      style={{
        width: box.width,
        height: box.height,
        transform: `translate(${box.left}px, ${box.top}px)`,
      }}
    />
  );
}

"use client";

import { useSyncExternalStore, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./kbd.css";

export type KbdPlatform = "mac" | "other";

/* Each key: the glyph people see on that platform, and the word a screen reader says. */
const named: Record<string, { mac: string; other: string; spoken: string; aria: string }> = {
  mod: { mac: "⌘", other: "Ctrl", spoken: "Command", aria: "Meta" },
  cmd: { mac: "⌘", other: "⌘", spoken: "Command", aria: "Meta" },
  meta: { mac: "⌘", other: "Win", spoken: "Command", aria: "Meta" },
  ctrl: { mac: "⌃", other: "Ctrl", spoken: "Control", aria: "Control" },
  alt: { mac: "⌥", other: "Alt", spoken: "Option", aria: "Alt" },
  option: { mac: "⌥", other: "Alt", spoken: "Option", aria: "Alt" },
  shift: { mac: "⇧", other: "Shift", spoken: "Shift", aria: "Shift" },
  enter: { mac: "↵", other: "Enter", spoken: "Enter", aria: "Enter" },
  return: { mac: "↵", other: "Enter", spoken: "Return", aria: "Enter" },
  esc: { mac: "Esc", other: "Esc", spoken: "Escape", aria: "Escape" },
  escape: { mac: "Esc", other: "Esc", spoken: "Escape", aria: "Escape" },
  tab: { mac: "⇥", other: "Tab", spoken: "Tab", aria: "Tab" },
  backspace: { mac: "⌫", other: "Backspace", spoken: "Backspace", aria: "Backspace" },
  delete: { mac: "⌦", other: "Del", spoken: "Delete", aria: "Delete" },
  space: { mac: "Space", other: "Space", spoken: "Space", aria: "Space" },
  up: { mac: "↑", other: "↑", spoken: "Up arrow", aria: "ArrowUp" },
  down: { mac: "↓", other: "↓", spoken: "Down arrow", aria: "ArrowDown" },
  left: { mac: "←", other: "←", spoken: "Left arrow", aria: "ArrowLeft" },
  right: { mac: "→", other: "→", spoken: "Right arrow", aria: "ArrowRight" },
  pageup: { mac: "PgUp", other: "PgUp", spoken: "Page up", aria: "PageUp" },
  pagedown: { mac: "PgDn", other: "PgDn", spoken: "Page down", aria: "PageDown" },
  home: { mac: "Home", other: "Home", spoken: "Home", aria: "Home" },
  end: { mac: "End", other: "End", spoken: "End", aria: "End" },
};

/** "mod+shift+k" or ["mod", "K"] → ["mod", "shift", "k"]. A lone "+" stays a key. */
function tokens(keys: string | readonly string[]) {
  if (typeof keys !== "string") return [...keys];
  if (keys === "+") return ["+"];
  return keys.split(/\+(?!$)/u).map((key) => key.trim()).filter(Boolean);
}

function describe(key: string, platform: KbdPlatform) {
  const known = named[key.toLowerCase()];
  if (known) return { glyph: known[platform], spoken: known.spoken, aria: known.aria };
  const glyph = key.length === 1 ? key.toUpperCase() : key;
  return { glyph, spoken: glyph, aria: glyph };
}

function detect(): KbdPlatform {
  const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
  const name = nav.userAgentData?.platform ?? nav.platform ?? "";
  return /mac|iphone|ipad|ipod/iu.test(name) ? "mac" : "other";
}

/** The platform's modifier names. The server renders "other"; Macs switch to ⌘ after hydration. */
export function useKbdPlatform(platform?: KbdPlatform): KbdPlatform {
  const detected = useSyncExternalStore(
    () => () => {},
    detect,
    () => "other" as const,
  );
  return platform ?? detected;
}

/** The value for `aria-keyshortcuts` on the control the keys trigger, e.g. "Meta+K". */
export function toAriaKeyshortcuts(keys: string | readonly string[], platform: KbdPlatform = "other") {
  return tokens(keys)
    .map((key) => {
      if (key.toLowerCase() === "mod") return platform === "mac" ? "Meta" : "Control";
      return describe(key, platform).aria;
    })
    .join("+");
}

export type KbdProps = Omit<ComponentProps<"kbd">, "children"> & {
  /** One key or a combination: "mod+k", "shift+enter", ["alt", "↑"]. `mod` is ⌘ on a Mac and Ctrl elsewhere. */
  keys?: string | readonly string[];
  /** Free text instead of keys, e.g. "G then D". */
  children?: string;
  /** `inline` sits quietly inside a button, menu row or tooltip and takes its colour. */
  variant?: "default" | "inline";
  size?: "sm" | "md";
  /** Force a platform instead of detecting it, e.g. in documentation. */
  platform?: KbdPlatform;
};

/**
 * Keys drawn as small raised caps. A combination is one `kbd` holding a cap
 * per key, so it reads as a single shortcut; symbols such as ⌘ carry their
 * spoken name for screen readers.
 */
export function Kbd({ keys, children, variant = "default", size = "md", platform, className, ...props }: KbdProps) {
  const resolved = useKbdPlatform(platform);
  const list = keys !== undefined ? tokens(keys) : children !== undefined ? [children] : [];
  const parts = list.map((key) => describe(key, resolved));
  const shared = { "data-variant": variant, "data-size": size } as const;
  if (parts.length === 1) {
    return (
      <kbd data-slot="kbd" {...shared} className={className} {...props}>
        <Glyph {...parts[0]!} />
      </kbd>
    );
  }
  return (
    <kbd data-slot="kbd-group" {...shared} className={cn(className)} {...props}>
      {parts.map((part, index) => (
        <kbd key={index} data-slot="kbd" {...shared}>
          {index > 0 && <span className="sr-only"> </span>}
          <Glyph {...part} />
        </kbd>
      ))}
    </kbd>
  );
}

function Glyph({ glyph, spoken }: { glyph: string; spoken: string }) {
  if (glyph === spoken) return glyph;
  return (
    <>
      <span aria-hidden="true">{glyph}</span>
      <span className="sr-only">{spoken}</span>
    </>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { Ellipsis } from "lucide-react";
import {
  createContext,
  Fragment,
  useCallback,
  useContext,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { Button } from "./button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "./dropdown-menu";
import { GlideHighlight, glideBox, type GlideBox } from "./glide-highlight";
import { Kbd } from "./kbd";
import { cn } from "./lib/cn";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "./tooltip";
import "./toolbar.css";

/* How each tool appears in the More menu once it no longer fits. */
type Entry =
  | { kind: "action"; label: string; icon?: ReactNode; disabled?: boolean; onSelect: () => void }
  | { kind: "toggle"; label: string; icon?: ReactNode; disabled?: boolean; checked: boolean; onSelect: () => void }
  | { kind: "option"; group: string; groupLabel: string; value: string; label: string; icon?: ReactNode; checked: boolean; onSelect: () => void };

type Ctx = { orientation: "horizontal" | "vertical"; hidden: ReadonlySet<string>; entries: Map<string, Entry> };
type Group = { id: string; label: string; type: "single" | "multiple"; values: readonly string[]; toggle: (value: string) => void };

const ToolbarContext = createContext<Ctx | null>(null);
const GroupContext = createContext<Group | null>(null);

/** Registers a tool's menu form after each render, so the menu always has the latest state. */
function useEntry(entry: Entry) {
  const ctx = useContext(ToolbarContext);
  const id = useId();
  useLayoutEffect(() => {
    if (!ctx) return;
    ctx.entries.set(id, entry);
    return () => void ctx.entries.delete(id);
  });
  return id;
}

/** A piece of the row that folds as one: a tool, a group or a separator. */
function useUnit() {
  const ctx = useContext(ToolbarContext);
  const id = useId();
  return { id, hidden: ctx?.hidden.has(id) ?? false, orientation: ctx?.orientation ?? "horizontal" };
}

const MORE = 36;
const focusables = "button:not(:disabled), input:not(:disabled), select:not(:disabled), a[href], [tabindex]:not([tabindex='-1'])";

/**
 * A row of tools with one tab stop. Arrows, Home and End move between them,
 * a toggled tool sits recessed in the shell, and when the row runs out of
 * width the last tools fold into a More menu that keeps their labels, state
 * and order. Fields inside keep their own arrow keys.
 */
export function Toolbar({
  label,
  orientation = "horizontal",
  overflow = true,
  className,
  children,
  ...props
}: Omit<ComponentProps<"div">, "role"> & {
  /** Names the toolbar, e.g. "Formatting". */
  label: string;
  orientation?: "horizontal" | "vertical";
  /** Fold tools that do not fit into a More menu (horizontal only). */
  overflow?: boolean;
}) {
  const root = useRef<HTMLDivElement>(null);
  const widths = useRef(new Map<string, number>());
  const [entries] = useState(() => new Map<string, Entry>());
  const [hidden, setHidden] = useState<ReadonlySet<string>>(() => new Set());
  const [menu, setMenu] = useState<Entry[][]>([]);
  const [box, setBox] = useState<GlideBox | null>(null);
  const folds = overflow && orientation === "horizontal";

  const items = useCallback(() => {
    const element = root.current;
    if (!element) return [];
    return [...element.querySelectorAll<HTMLElement>("[data-toolbar-item], [data-toolbar-generic]")]
      .filter((node) => !node.closest("[data-overflowed]"))
      .map((node) => (node.hasAttribute("data-toolbar-item") ? node : node.querySelector<HTMLElement>(focusables)))
      .filter((node): node is HTMLElement => !!node && !(node as HTMLButtonElement).disabled);
  }, []);

  const activate = useCallback((node: HTMLElement) => {
    for (const other of items()) {
      other.tabIndex = other === node ? 0 : -1;
      if (other !== node) delete other.dataset.toolbarActive;
    }
    node.dataset.toolbarActive = "";
  }, [items]);

  // One tab stop: the tool used last, or the first one.
  useLayoutEffect(() => {
    const list = items();
    if (!list.length) return;
    const current = list.find((node) => node.dataset.toolbarActive !== undefined) ?? list[0]!;
    for (const node of list) node.tabIndex = node === current ? 0 : -1;
  });

  const fit = useCallback(() => {
    const element = root.current;
    if (!element || !folds) return;
    const units = [...element.querySelectorAll<HTMLElement>("[data-toolbar-unit]")];
    for (const unit of units) if (!unit.hasAttribute("data-overflowed")) widths.current.set(unit.dataset.toolbarUnit!, unit.offsetWidth + 2);
    const width = (unit: HTMLElement) => widths.current.get(unit.dataset.toolbarUnit!) ?? 0;
    const available = element.clientWidth - 6;
    const next = new Set<string>();
    if (units.reduce((sum, unit) => sum + width(unit), 0) > available) {
      let budget = available - MORE - units.filter((unit) => unit.dataset.pinned !== undefined).reduce((sum, unit) => sum + width(unit), 0);
      let full = false;
      for (const unit of units) {
        if (unit.dataset.pinned !== undefined) continue;
        if (!full && width(unit) <= budget) budget -= width(unit);
        else {
          full = true;
          next.add(unit.dataset.toolbarUnit!);
        }
      }
      // No separator left dangling at the end of the row.
      for (let i = units.length - 1; i >= 0; i -= 1) {
        const unit = units[i]!;
        if (next.has(unit.dataset.toolbarUnit!) || unit.dataset.pinned !== undefined) continue;
        if (unit.dataset.separator !== undefined) next.add(unit.dataset.toolbarUnit!);
        else break;
      }
    }
    setHidden((current) => (current.size === next.size && [...next].every((id) => current.has(id)) ? current : next));
  }, [folds]);

  useLayoutEffect(() => {
    const element = root.current;
    if (!element || !folds) return;
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(element);
    return () => observer.disconnect();
  }, [fit, folds]);

  function move(event: KeyboardEvent<HTMLDivElement>) {
    const target = event.target as HTMLElement;
    if (target.matches("input, textarea, [contenteditable='true']")) return;
    const back = orientation === "horizontal" ? "ArrowLeft" : "ArrowUp";
    const forward = orientation === "horizontal" ? "ArrowRight" : "ArrowDown";
    if (![back, forward, "Home", "End"].includes(event.key)) return;
    const list = items();
    const index = list.findIndex((node) => node === target || node.contains(target));
    if (index < 0) return;
    event.preventDefault();
    const next = event.key === "Home" ? 0 : event.key === "End" ? list.length - 1 : (index + (event.key === forward ? 1 : -1) + list.length) % list.length;
    activate(list[next]!);
    list[next]!.focus();
  }

  function place(target: EventTarget | null) {
    const button = target instanceof Element ? target.closest<HTMLElement>('[data-slot="button"]') : null;
    if (!button || !root.current?.contains(button)) return;
    setBox(glideBox(button));
  }
  const rest = () => setBox((current) => (current ? { ...current, active: false } : null));

  function openMenu(open: boolean) {
    if (!open || !root.current) return;
    // Units in row order, each with its tools in order.
    const units = [...root.current.querySelectorAll<HTMLElement>("[data-toolbar-unit][data-overflowed]")];
    setMenu(
      units
        .map((unit) => [...unit.querySelectorAll<HTMLElement>("[data-toolbar-entry]")].map((node) => entries.get(node.dataset.toolbarEntry!)).filter((entry): entry is Entry => !!entry))
        .filter((list) => list.length > 0),
    );
  }

  return (
    <ToolbarContext.Provider value={{ orientation, hidden, entries }}>
      <TooltipProvider>
        <div
          {...props}
          ref={root}
          role="toolbar"
          aria-label={label}
          aria-orientation={orientation}
          data-slot="toolbar"
          data-orientation={orientation}
          onKeyDown={(event) => {
            move(event);
            props.onKeyDown?.(event);
          }}
          onFocus={(event) => {
            const node = items().find((item) => item === event.target || item.contains(event.target as Node));
            if (node) activate(node);
            place(event.target);
          }}
          onBlur={(event) => !root.current?.contains(event.relatedTarget as Node) && rest()}
          onPointerMove={(event) => place(event.target)}
          onPointerLeave={rest}
          className={cn(
            "relative flex max-w-full min-w-0 gap-0.5 rounded-touch bg-raised p-[3px] shadow-raised",
            orientation === "vertical" ? "inline-flex flex-col" : "items-center",
            className,
          )}
        >
          <GlideHighlight box={box} />
          {children}
          {folds && hidden.size > 0 && (
            <DropdownMenu onOpenChange={openMenu}>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon" data-toolbar-item="" aria-label="More tools" className="ml-auto">
                  <Ellipsis aria-hidden="true" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                {menu.map((list, index) => (
                  <Fragment key={index}>
                    {/* Single tools sit together; groups get a rule either side. */}
                    {index > 0 && (list.length > 1 || menu[index - 1]!.length > 1) && <DropdownMenuSeparator />}
                    <MenuUnit entries={list} />
                  </Fragment>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          )}
        </div>
      </TooltipProvider>
    </ToolbarContext.Provider>
  );
}

function MenuUnit({ entries }: { entries: Entry[] }) {
  const first = entries[0]!;
  if (first.kind === "option") {
    const chosen = entries.find((entry) => entry.kind === "option" && entry.checked);
    return (
      <>
        <DropdownMenuLabel>{first.groupLabel}</DropdownMenuLabel>
        <DropdownMenuRadioGroup value={chosen?.kind === "option" ? chosen.value : ""}>
          {entries.map((entry) =>
            entry.kind === "option" ? (
              <DropdownMenuRadioItem key={entry.value} value={entry.value} onSelect={entry.onSelect}>
                {entry.icon}
                {entry.label}
              </DropdownMenuRadioItem>
            ) : null,
          )}
        </DropdownMenuRadioGroup>
      </>
    );
  }
  return entries.map((entry) =>
    entry.kind === "toggle" ? (
      <DropdownMenuCheckboxItem key={entry.label} checked={entry.checked} disabled={entry.disabled} onSelect={entry.onSelect}>
        {entry.label}
      </DropdownMenuCheckboxItem>
    ) : entry.kind === "action" ? (
      <DropdownMenuItem key={entry.label} disabled={entry.disabled} onSelect={entry.onSelect}>
        {entry.icon}
        {entry.label}
      </DropdownMenuItem>
    ) : null,
  );
}

function ToolTip({ label, shortcut, show, children }: { label: string; shortcut?: string; show: boolean; children: ReactNode }) {
  if (!show && !shortcut) return children;
  return (
    <Tooltip>
      <TooltipTrigger asChild>{children}</TooltipTrigger>
      <TooltipContent>
        {label}
        {shortcut && <Kbd keys={shortcut} variant="inline" size="sm" />}
      </TooltipContent>
    </Tooltip>
  );
}

/**
 * One tool. With an icon and no `showLabel`, the label becomes its accessible
 * name and tooltip. Pass `pressed` to make it a toggle such as Bold.
 */
export function ToolbarButton({
  label,
  icon,
  showLabel = !icon,
  shortcut,
  pressed,
  onPressedChange,
  onClick,
  pinned = false,
  disabled,
  className,
}: {
  label: string;
  icon?: ReactNode;
  showLabel?: boolean;
  /** Shown in the tooltip, e.g. "mod+b". Your app listens for the keys. */
  shortcut?: string;
  pressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  onClick?: () => void;
  /** Never folds into the More menu. */
  pinned?: boolean;
  disabled?: boolean;
  className?: string;
}) {
  const toggle = pressed !== undefined;
  const activate = () => (toggle ? onPressedChange?.(!pressed) : onClick?.());
  const entry = useEntry(toggle ? { kind: "toggle", label, icon, disabled, checked: !!pressed, onSelect: activate } : { kind: "action", label, icon, disabled, onSelect: activate });
  const unit = useUnit();
  return (
    <span data-toolbar-unit={unit.id} data-pinned={pinned ? "" : undefined} data-overflowed={unit.hidden ? "" : undefined}>
      <ToolTip label={label} shortcut={shortcut} show={!showLabel}>
        <Button
          variant="ghost"
          size={showLabel ? "sm" : "icon"}
          data-toolbar-item=""
          data-toolbar-entry={entry}
          aria-pressed={toggle ? pressed : undefined}
          aria-label={showLabel ? undefined : label}
          disabled={disabled}
          onClick={activate}
          className={className}
        >
          {icon}
          {showLabel && label}
        </Button>
      </ToolTip>
    </span>
  );
}

/**
 * Tools that belong together and fold together: `single` is one choice such
 * as alignment (a radio group), `multiple` is independent toggles such as
 * bold and italic.
 */
export function ToolbarToggleGroup({
  label,
  pinned = false,
  children,
  ...choice
}: {
  label: string;
  pinned?: boolean;
  children: ReactNode;
} & (
  | { type: "single"; value: string; onValueChange: (value: string) => void }
  | { type: "multiple"; value: readonly string[]; onValueChange: (value: string[]) => void }
)) {
  const { type } = choice;
  const unit = useUnit();
  const values = choice.type === "single" ? (choice.value ? [choice.value] : []) : choice.value;
  const toggle = (item: string) => {
    if (choice.type === "single") choice.onValueChange(item);
    else choice.onValueChange(values.includes(item) ? values.filter((v) => v !== item) : [...values, item]);
  };
  return (
    <GroupContext.Provider value={{ id: unit.id, label, type, values, toggle }}>
      <span
        role={type === "single" ? "radiogroup" : "group"}
        aria-label={label}
        data-slot="toolbar-group"
        data-toolbar-unit={unit.id}
        data-pinned={pinned ? "" : undefined}
        data-overflowed={unit.hidden ? "" : undefined}
      >
        {children}
      </span>
    </GroupContext.Provider>
  );
}

export function ToolbarToggleItem({ value, label, icon, shortcut, disabled }: { value: string; label: string; icon?: ReactNode; shortcut?: string; disabled?: boolean }) {
  const group = useContext(GroupContext);
  if (!group) throw new Error("ToolbarToggleItem belongs inside a ToolbarToggleGroup.");
  const on = group.values.includes(value);
  const single = group.type === "single";
  const select = () => group.toggle(value);
  const entry = useEntry(
    single
      ? { kind: "option", group: group.id, groupLabel: group.label, value, label, icon, checked: on, onSelect: select }
      : { kind: "toggle", label, icon, disabled, checked: on, onSelect: select },
  );
  return (
    <ToolTip label={label} shortcut={shortcut} show={!!icon}>
      <Button
        variant="ghost"
        size={icon ? "icon" : "sm"}
        data-toolbar-item=""
        data-toolbar-entry={entry}
        role={single ? "radio" : undefined}
        aria-checked={single ? on : undefined}
        aria-pressed={single ? undefined : on}
        data-on={on || undefined}
        aria-label={icon ? label : undefined}
        disabled={disabled}
        onClick={select}
      >
        {icon ?? label}
      </Button>
    </ToolTip>
  );
}

export function ToolbarSeparator() {
  const unit = useUnit();
  return (
    <span
      role="separator"
      aria-orientation={unit.orientation === "vertical" ? "horizontal" : "vertical"}
      data-slot="toolbar-separator"
      data-toolbar-unit={unit.id}
      data-separator=""
      data-overflowed={unit.hidden ? "" : undefined}
    />
  );
}

/**
 * Any other control in the row, such as a SelectMenu or a zoom field. It
 * joins the arrow-key order and stays visible when the row folds.
 */
export function ToolbarItem({ children, className }: { children: ReactNode; className?: string }) {
  const unit = useUnit();
  return (
    <span data-toolbar-unit={unit.id} data-toolbar-generic="" data-pinned="" className={className}>
      {children}
    </span>
  );
}

"use client";

import * as TooltipPrimitive from "@radix-ui/react-tooltip";
import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./tooltip.css";

export const Tooltip = TooltipPrimitive.Root;
export const TooltipTrigger = TooltipPrimitive.Trigger;

/**
 * The first tooltip waits 300ms; neighbours then show at once for 500ms.
 * Tooltips are labels, not panels, so their content is not hoverable: moving
 * along a toolbar switches straight to the next label.
 */
export function TooltipProvider({
  delayDuration = 300,
  skipDelayDuration = 500,
  disableHoverableContent = true,
  ...props
}: ComponentProps<typeof TooltipPrimitive.Provider>) {
  return (
    <TooltipPrimitive.Provider
      delayDuration={delayDuration}
      skipDelayDuration={skipDelayDuration}
      disableHoverableContent={disableHoverableContent}
      {...props}
    />
  );
}

export function TooltipContent({
  className,
  sideOffset = 6,
  shortcut,
  children,
  ...props
}: ComponentProps<typeof TooltipPrimitive.Content> & {
  /** Keyboard shortcut shown after the label, e.g. "⌘D". */
  shortcut?: string;
}) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-slot="tooltip-content"
        sideOffset={sideOffset}
        className={cn(
          "z-50 inline-flex max-w-60 items-center gap-2 rounded-control bg-foreground px-2.5 py-1.5 text-xs leading-4 font-medium text-background shadow-feedback",
          className,
        )}
        {...props}
      >
        {children}
        {shortcut && <kbd data-slot="tooltip-shortcut">{shortcut}</kbd>}
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
}

