    position: relative; z-index: 1; height: calc(var(--control-height) - 6px); border-radius: 8px;
    --b-bg: transparent; --b-bg-hover: transparent; --b-bg-press: var(--muted); --b-fg: var(--foreground); --b-shadow: none; --b-shadow-press: none;
  }
  [data-slot="toolbar"] [data-slot="button"][data-size="icon"] { width: calc(var(--control-height) - 6px); }
  [data-slot="toolbar"] [data-slot="button"]:is([aria-pressed="true"], [aria-checked="true"], [data-state="open"]) {
    --b-bg: var(--sunken); --b-bg-hover: var(--sunken); --b-bg-press: var(--sunken); --b-shadow: var(--shadow-sunken); --b-shadow-press: var(--shadow-sunken);
  }
  [data-slot="toolbar"] [data-toolbar-generic] button { height: calc(var(--control-height) - 6px); }
  [data-slot="toolbar"] [data-toolbar-unit] { display: inline-flex; flex: none; gap: 2px; }
  [data-slot="toolbar"] [data-toolbar-unit][data-overflowed] { display: none; }
  [data-slot="toolbar-separator"] { flex: none; align-self: stretch; width: 1px; margin: 6px 3px; background: var(--border); }
  [data-slot="toolbar"][data-orientation="vertical"] [data-slot="toolbar-separator"] { width: auto; height: 1px; margin: 3px 6px; }
  [data-slot="toolbar"][data-orientation="vertical"] [data-slot="toolbar-group"] { flex-direction: column; }
  @media (pointer: coarse) {
    [data-slot="toolbar"] [data-slot="button"] { height: 40px; }
    [data-slot="toolbar"] [data-slot="button"][data-size="icon"] { width: 40px; }
  }
}

/* tooltip.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* The first tooltip fades in; while warm, neighbours swap with no animation. */
  [data-slot="tooltip-content"][data-state="delayed-open"] {
    animation: caliper-fade-in var(--duration-fast) var(--ease-out);
  }
  [data-slot="tooltip-shortcut"] {
    display: inline-flex;
    align-items: center;
    height: 18px;
    padding: 0 5px;
    border-radius: 4px;
    font-family: var(--font-mono);
    font-size: 12px;
    font-weight: 500;
    background: color-mix(in srgb, var(--background) 16%, transparent);
  }

  [data-slot="tooltip-content"][data-state="closed"] {
    animation: caliper-fade-out var(--duration-fast) var(--ease-in) forwards;
    pointer-events: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="tooltip-content"] {
      animation: none;
    }
    /* Preserve the exit name for Radix Presence's completion matcher, including
       a preference changed during exit. No visual motion or unmount timer. */
    [data-slot="tooltip-content"][data-state="closed"] {
      animation: caliper-fade-out var(--duration-instant) var(--ease-in) forwards !important;
    }
  }
}
